import numpy as np

def ritzpair2(B):
    a,b = B[0,0], B[0,1]
    c,d = B[1,0], B[1,1]
    tr=(a+d)/2
    disc=((a-d)/2)**2 + b*c
    if disc>=0:
        r=np.sqrt(disc); vals=(tr+r, tr-r)
    else:
        r=np.sqrt(-disc); vals=(tr+1j*r, tr-1j*r)
    if abs(vals[0])>=abs(vals[1]):
        lam=vals[0]; other=vals[1]
    else:
        lam=vals[1]; other=vals[0]
    if b!=0: y=np.array([b, lam-a],dtype=complex)
    elif c!=0: y=np.array([lam-d, c],dtype=complex)
    else:
        y=np.array([1,0],dtype=complex) if abs(a)>=abs(d) else np.array([0,1],dtype=complex)
    n=np.linalg.norm(y)
    return lam, y/n, other

FIX = np.array([1.0,-1.0,0.7,-0.3,1.3,-1.7,0.2,-0.9,1.1,-0.5])

def orth2(Y):
    n=Y.shape[0]
    q1=Y[:,0].copy(); q1/=np.linalg.norm(q1)
    v=Y[:,1]-np.dot(q1,Y[:,1])*q1
    nv=np.linalg.norm(v)
    if nv < 1e-8*np.linalg.norm(Y[:,1]):
        v=FIX[:n]-np.dot(q1,FIX[:n])*q1; nv=np.linalg.norm(v)
    return np.column_stack([q1,v/nv])

def dom(A, SMAX=30, tol=1e-10, verbose=False):
    n=A.shape[0]
    nrm=np.linalg.norm(A)
    if nrm==0: return 0.0, np.array([1.0]+[0.0]*(n-1))
    H=A/nrm
    i=np.arange(1,n+1,dtype=np.float64)
    X=np.column_stack([np.sin(1.234*i)+np.cos(0.777*i), np.cos(0.531*i)-np.sin(1.117*i)])
    best=None
    prev=None
    for s in range(0,SMAX):
        if s>0:
            H=H@H; m=np.abs(H).max()
            if not np.isfinite(m) or m==0: break
            H=H/m
        Y=H@X
        if not np.all(np.isfinite(Y)): break
        Q=orth2(Y)
        B=Q.T@(A@Q)
        lam,y,other=ritzpair2(B)
        q=Q@y; q=q/np.linalg.norm(q)
        Ax=A@q
        rq=np.vdot(q,Ax)/np.vdot(q,q)
        res=np.linalg.norm(Ax-rq*q)/nrm
        if best is None or res<best[0]: best=(res,rq,q,lam)
        if res<tol:
            if verbose: print("converged at s",s,res)
            return rq,q
        if prev is not None and abs(lam-prev)<=1e-12*nrm:
            if verbose: print("stall at s",s,res)
            break
        prev=lam
    if verbose: print("fallback, best res",best[0])
    return best[1],best[2]

if __name__=="__main__":
    rng=np.random.default_rng(0)
    for dist in ["normal","unif","exp","cauchy"]:
        fails=0; tot=0; worst=0; wrong=0; maxs=0
        for n in range(2,11):
            for _ in range(3000):
                if dist=="normal": A=rng.normal(size=(n,n))
                elif dist=="unif": A=rng.uniform(-1,1,size=(n,n))
                elif dist=="exp": A=rng.exponential(size=(n,n))
                else: A=rng.standard_cauchy(size=(n,n))
                lam,q=dom(A)
                res=np.linalg.norm(A@q-lam*q)/np.linalg.norm(A)
                worst=max(worst,res); tot+=1
                if not np.allclose(A@q, lam*q, rtol=1e-5, atol=1e-8): fails+=1
                w=np.linalg.eigvals(A); true=np.max(np.abs(w))
                if abs(abs(lam)-true)>1e-6*true: wrong+=1
        print(f"{dist}: fails={fails}/{tot} worst={worst:.2e} wrongdom={wrong}")
